typedef struct { const char *name; const unsigned char *data; unsigned size; int kind; const void *ref; int nref; int w, h; int pf; const void *ref1; } TImage;
typedef struct { int x, y; unsigned argb; } TSample;
#include "gdiplus_img/images.h"

static const CLSID CLSID_PNG = { 0x557CF406, 0x1A04, 0x11D3, { 0x9A, 0x73, 0x00, 0x00, 0xF8, 0x1E, 0xF3, 0x2E } };
static const CLSID CLSID_BMP = { 0x557CF400, 0x1A04, 0x11D3, { 0x9A, 0x73, 0x00, 0x00, 0xF8, 0x1E, 0xF3, 0x2E } };
static const GUID DIM_TIME = { 0x6AEDBD6D, 0x3FB5, 0x418A, { 0x83, 0xA6, 0x7F, 0x45, 0x22, 0x9D, 0xC8, 0x72 } };

#define PF_ARGB 0x26200A
#define PF_24 0x21808
#define BW 240
#define BH 180

static unsigned *bits;
static unsigned px(int x, int y) { return bits[y * BW + x] & 0xFFFFFF; }
static void rgb(const char *what, int x, int y, unsigned want) {
    unsigned v = px(x, y);
    printf("%s (%d,%d) %s\n", what, x, y, v == want ? "ok" : "bad");
    if (v != want) printf("  got %06X want %06X\n", v, want);
}
static int near_c(unsigned v, unsigned want, int tol) {
    for (int s = 0; s < 24; s += 8) { int d = (int)((v >> s) & 255) - (int)((want >> s) & 255); if (d < -tol || d > tol) return 0; }
    return 1;
}
static void gp(const char *what, GpStatus s) { if (s) printf("%s failed: %d\n", what, s); }

static WCHAR *wide(const char *s) { static WCHAR buf[4][260]; static int n; WCHAR *w = buf[n++ & 3]; int i = 0; while ((w[i] = (unsigned char)s[i])) i++; return w; }

static void graphics_tests(void) {
    BITMAPINFO bi; memset(&bi, 0, sizeof bi);
    bi.bmiHeader.biSize = sizeof bi.bmiHeader; bi.bmiHeader.biWidth = BW; bi.bmiHeader.biHeight = -BH; bi.bmiHeader.biPlanes = 1; bi.bmiHeader.biBitCount = 32;
    HDC dc = CreateCompatibleDC(NULL);
    HBITMAP dib = CreateDIBSection(dc, &bi, DIB_RGB_COLORS, (void **)&bits, NULL, 0);
    HGDIOBJ old = SelectObject(dc, dib);
    H g = NULL, br = NULL, pen = NULL;
    gp("CreateFromHDC", GdipCreateFromHDC(dc, &g));
    GdipGraphicsClear(g, 0xFFFFFFFF);
    rgb("clear white", 5, 5, 0xFFFFFF);
    // aliased red rectangle
    GdipSetSmoothingMode(g, 3);
    GdipCreateSolidFill(0xFFFF0000, &br);
    GdipFillRectangle(g, br, 20, 20, 40, 30);
    rgb("rect inside", 20, 20, 0xFF0000); rgb("rect inside", 59, 49, 0xFF0000); rgb("rect inside", 40, 35, 0xFF0000);
    rgb("rect outside", 60, 49, 0xFFFFFF); rgb("rect outside", 19, 20, 0xFFFFFF); rgb("rect outside", 20, 50, 0xFFFFFF); rgb("rect outside", 59, 19, 0xFFFFFF);
    GdipDeleteBrush(br);
    // antialiased ellipse
    GdipSetSmoothingMode(g, 4);
    GdipCreateSolidFill(0xFF0000FF, &br);
    GdipFillEllipse(g, br, 100, 20, 60, 40);
    rgb("ellipse centre", 130, 40, 0x0000FF); rgb("ellipse centre", 120, 35, 0x0000FF); rgb("ellipse outside", 96, 40, 0xFFFFFF); rgb("ellipse outside", 130, 15, 0xFFFFFF);
    int partial = 0; // pixels along the upper left edge that are blended (neither background nor fill)
    for (int y = 22; y < 30; y++) for (int x = 104; x < 114; x++) { unsigned e = px(x, y); if (e != 0xFFFFFF && e != 0x0000FF && (e & 0xFF) == 0xFF) partial++; }
    printf("ellipse edge %s\n", partial >= 3 ? "partial" : "not partial");
    GdipDeleteBrush(br);
    // pen of width 3
    GdipSetSmoothingMode(g, 3);
    GdipCreatePen1(0xFF000000, 3, 2, &pen);
    GdipDrawLine(g, pen, 10, 100, 110, 100);
    rgb("line centre", 60, 100, 0x000000); rgb("line centre", 11, 100, 0x000000); rgb("line far", 60, 104, 0xFFFFFF); rgb("line far", 60, 96, 0xFFFFFF); rgb("line end", 115, 100, 0xFFFFFF);
    GdipDeletePen(pen);
    // translate + rotate 90 degrees
    GdipCreateSolidFill(0xFF008000, &br);
    GdipTranslateWorldTransform(g, 100, 120, 0);
    GdipRotateWorldTransform(g, 90, 0);
    GdipFillRectangle(g, br, 0, 0, 20, 10);
    GdipResetWorldTransform(g);
    rgb("rotated rect", 95, 130, 0x008000); rgb("rotated rect", 91, 122, 0x008000); rgb("rotated rect", 98, 138, 0x008000);
    rgb("rotated outside", 105, 130, 0xFFFFFF); rgb("rotated outside", 95, 145, 0xFFFFFF); rgb("rotated outside", 110, 125, 0xFFFFFF); rgb("rotated outside", 85, 130, 0xFFFFFF);
    GdipDeleteBrush(br);
    // clip
    GdipCreateSolidFill(0xFFFF00FF, &br);
    GdipSetClipRect(g, 150, 100, 30, 30, 0);
    GdipFillRectangle(g, br, 130, 90, 100, 100);
    GdipResetClip(g);
    rgb("clipped fill", 160, 110, 0xFF00FF); rgb("clipped fill", 150, 100, 0xFF00FF); rgb("clipped fill", 179, 129, 0xFF00FF);
    rgb("clip outside", 145, 110, 0xFFFFFF); rgb("clip outside", 190, 110, 0xFFFFFF); rgb("clip outside", 160, 95, 0xFFFFFF); rgb("clip outside", 160, 131, 0xFFFFFF);
    GdipDeleteBrush(br);
    // linear gradient red -> blue
    {
        PointF a = { 0, 150 }, b = { 100, 150 };
        H lb = NULL;
        gp("LineBrush", GdipCreateLineBrush(&a, &b, 0xFFFF0000, 0xFF0000FF, 0, &lb));
        GdipFillRectangle(g, lb, 0, 150, 100, 20);
        printf("gradient start %s\n", near_c(px(0, 160), 0xFF0000, 4) ? "ok" : "bad");
        printf("gradient end %s\n", near_c(px(99, 160), 0x0000FF, 4) ? "ok" : "bad");
        printf("gradient mid %s\n", near_c(px(50, 160), 0x800080, 4) ? "ok" : "bad");
        printf("gradient quarter %s\n", near_c(px(25, 165), 0xBF0040, 4) ? "ok" : "bad");
        rgb("gradient outside", 100, 160, 0xFFFFFF); rgb("gradient outside", 50, 170, 0xFFFFFF);
        GdipDeleteBrush(lb);
    }
    // text
    {
        H fam = NULL, font = NULL, fb = NULL;
        gp("FontFamily", GdipCreateFontFamilyFromName(wide("Arial"), NULL, &fam));
        gp("Font", GdipCreateFont(fam, 14, 0, 2, &font));
        GdipCreateSolidFill(0xFF000000, &fb);
        RectF rc = { 110, 140, 120, 30 };
        const WCHAR *txt = wide("Merhaba GDI+");
        GdipSetSmoothingMode(g, 3);
        gp("DrawString", GdipDrawString(g, txt, -1, font, &rc, NULL, fb));
        int dark = 0, stray = 0;
        for (int y = 140; y < 170; y++) for (int x = 110; x < 230; x++) if ((px(x, y) & 0xFF) < 128) dark++;
        for (int y = 131; y < 140; y++) for (int x = 110; x < 230; x++) if (px(x, y) != 0xFFFFFF) stray++;
        for (int y = 140; y < 180; y++) for (int x = 101; x < 110; x++) if (px(x, y) != 0xFFFFFF) stray++;
        for (int y = 171; y < 180; y++) for (int x = 101; x < 240; x++) if (px(x, y) != 0xFFFFFF) stray++;
        for (int y = 140; y < 180; y++) for (int x = 230; x < 240; x++) if (px(x, y) != 0xFFFFFF) stray++;
        printf("text dark pixels inside: %s\n", dark > 20 ? "yes" : "no");
        printf("text stray pixels outside: %d\n", stray);
        RectF box; int fitted = 0, lines = 0;
        RectF big = { 0, 0, 0, 0 };
        gp("MeasureString", GdipMeasureString(g, txt, -1, font, &big, NULL, &box, &fitted, &lines));
        float lh = 0; GdipGetFontHeight(font, g, &lh);
        printf("measure width %s height %s fitted %d lines %d\n", box.w > 20 ? "ok" : "bad", (box.h > lh - 1 && box.h < lh + 1 && lh > 10 && lh < 25) ? "ok" : "bad", fitted, lines);
        // narrow rectangle: wraps into two lines
        RectF narrow = { 0, 0, 60, 100 };
        gp("MeasureString", GdipMeasureString(g, txt, -1, font, &narrow, NULL, &box, &fitted, &lines));
        printf("wrapped lines %d fitted %d width %s\n", lines, fitted, box.w <= 60.01f ? "ok" : "bad");
        GdipDeleteBrush(fb); GdipDeleteFont(font); GdipDeleteFontFamily(fam);
    }
    GdipDeleteGraphics(g);
    SelectObject(dc, old); DeleteObject(dib); DeleteDC(dc);
}

static void path_region_tests(void) {
    H path = NULL, rg = NULL, m = NULL;
    GdipCreatePath(0, &path);
    GdipAddPathRectangle(path, 10, 20, 30, 40);
    GdipCreateRegionPath(path, &rg);
    RectF r = { 20, 30, 100, 100 };
    GdipCombineRegionRect(rg, &r, 1); // intersect
    RectF b;
    GdipGetRegionBounds(rg, NULL, &b);
    printf("region bounds %d %d %d %d\n", (int)b.x, (int)b.y, (int)b.w, (int)b.h);
    GdipDeleteRegion(rg); GdipDeletePath(path);
    GdipCreateMatrix2(2, 0, 0, 3, 5, 7, &m);
    PointF p[2] = { { 1, 1 }, { 10, 20 } };
    GdipTransformMatrixPoints(m, p, 2);
    printf("matrix points %d,%d %d,%d\n", (int)p[0].x, (int)p[0].y, (int)p[1].x, (int)p[1].y);
    GdipDeleteMatrix(m);
}

static int same_bitmap(H a, H b, UINT w, UINT h) {
    for (UINT y = 0; y < h; y++) for (UINT x = 0; x < w; x++) {
        UINT p = 0, q = 1;
        GdipBitmapGetPixel(a, x, y, &p); GdipBitmapGetPixel(b, x, y, &q);
        if (p != q) { printf("  differs at %u,%u: %08X vs %08X\n", x, y, p, q); return 0; }
    }
    return 1;
}

static void bitmap_tests(void) {
    H bmp = NULL, g = NULL, br = NULL;
    gp("Scan0", GdipCreateBitmapFromScan0(32, 32, 0, PF_ARGB, NULL, &bmp));
    UINT w = 0, h = 0; int pf = 0;
    GdipGetImageWidth(bmp, &w); GdipGetImageHeight(bmp, &h); GdipGetImagePixelFormat(bmp, &pf);
    printf("bitmap %ux%u format %X\n", w, h, pf);
    gp("ImageGraphics", GdipGetImageGraphicsContext(bmp, &g));
    GdipGraphicsClear(g, 0xFF102030);
    GdipSetSmoothingMode(g, 3);
    GdipCreateSolidFill(0xFFFF0000, &br);
    GdipFillRectangle(g, br, 4, 4, 8, 8);
    GdipDeleteBrush(br); GdipDeleteGraphics(g);
    BmpData bd; RectI all = { 0, 0, 32, 32 };
    gp("LockBits", GdipBitmapLockBits(bmp, &all, 3, PF_ARGB, &bd));
    unsigned *p = (unsigned *)bd.Scan0;
    int stride = bd.Stride / 4;
    printf("lock %ux%u stride %d fmt %X\n", bd.Width, bd.Height, bd.Stride, bd.PixelFormat);
    printf("scan0 %08X %08X %08X\n", p[0], p[5 * stride + 5], p[12 * stride + 12]);
    p[31 * stride + 31] = 0xFF00FF00;
    gp("Unlock", GdipBitmapUnlockBits(bmp, &bd));
    UINT v = 0;
    GdipBitmapGetPixel(bmp, 31, 31, &v); printf("pixel 31,31 %08X\n", v);
    GdipBitmapGetPixel(bmp, 5, 5, &v); printf("pixel 5,5 %08X\n", v);
    GdipBitmapSetPixel(bmp, 1, 1, 0x80FFFFFF);
    GdipBitmapGetPixel(bmp, 1, 1, &v); printf("pixel 1,1 %08X\n", v);
    // 24 bpp lock with write back
    RectI r2 = { 0, 0, 2, 2 };
    BmpData b2;
    gp("LockBits24", GdipBitmapLockBits(bmp, &r2, 3, PF_24, &b2));
    unsigned char *q = (unsigned char *)b2.Scan0;
    printf("lock24 stride %d first %02X%02X%02X\n", b2.Stride, q[0], q[1], q[2]);
    q[0] = 1; q[1] = 2; q[2] = 3;
    GdipBitmapUnlockBits(bmp, &b2);
    GdipBitmapGetPixel(bmp, 0, 0, &v); printf("pixel 0,0 after 24bpp write %08X\n", v);
    GdipBitmapGetPixel(bmp, 1, 1, &v); printf("pixel 1,1 alpha after 24bpp write %s\n", (v >> 24) == 0xFF ? "opaque" : "kept");
    // HBITMAP round trip
    {
        GdipBitmapSetPixel(bmp, 1, 1, 0xFF405060);
        HBITMAP hb = NULL;
        gp("HBITMAP", GdipCreateHBITMAPFromBitmap(bmp, &hb, 0xFFFFFFFF));
        BITMAPINFO bi; memset(&bi, 0, sizeof bi);
        bi.bmiHeader.biSize = sizeof bi.bmiHeader; bi.bmiHeader.biWidth = 32; bi.bmiHeader.biHeight = -32; bi.bmiHeader.biPlanes = 1; bi.bmiHeader.biBitCount = 32;
        unsigned out[32 * 32];
        HDC dc = CreateCompatibleDC(NULL);
        int n = GetDIBits(dc, hb, 0, 32, out, &bi, DIB_RGB_COLORS);
        printf("GetDIBits %d lines: %06X %06X %06X %06X\n", n, out[0] & 0xFFFFFF, out[5 * 32 + 5] & 0xFFFFFF, out[31 * 32 + 31] & 0xFFFFFF, out[33] & 0xFFFFFF);
        DeleteDC(dc); DeleteObject(hb);
    }
    // save as PNG and BMP, reload, compare
    {
        H re = NULL;
        printf("save png %d\n", GdipSaveImageToFile(bmp, wide("gdiplus_t.png"), &CLSID_PNG, NULL));
        printf("load png %d\n", GdipCreateBitmapFromFile(wide("gdiplus_t.png"), &re));
        UINT rw = 0, rh = 0; GdipGetImageWidth(re, &rw); GdipGetImageHeight(re, &rh);
        printf("png %ux%u same pixels %s\n", rw, rh, same_bitmap(bmp, re, 32, 32) ? "yes" : "no");
        GdipDisposeImage(re);
        // BMP: opaque pixels only
        GdipBitmapSetPixel(bmp, 0, 0, 0xFF010203);
        printf("save bmp %d\n", GdipSaveImageToFile(bmp, wide("gdiplus_t.bmp"), &CLSID_BMP, NULL));
        printf("load bmp %d\n", GdipCreateBitmapFromFile(wide("gdiplus_t.bmp"), &re));
        GdipGetImageWidth(re, &rw); GdipGetImageHeight(re, &rh);
        printf("bmp %ux%u same pixels %s\n", rw, rh, same_bitmap(bmp, re, 32, 32) ? "yes" : "no");
        GdipDisposeImage(re);
        DeleteFileA("gdiplus_t.png"); DeleteFileA("gdiplus_t.bmp");
        // PNG through a memory stream: save then read back with GdipCreateBitmapFromStream
        IStream *ms = NULL;
        CreateStreamOnHGlobal(NULL, TRUE, &ms);
        printf("save to stream %d\n", GdipSaveImageToStream(bmp, ms, &CLSID_PNG, NULL));
        LARGE_INTEGER z; z.QuadPart = 0;
        ms->lpVtbl->Seek(ms, z, STREAM_SEEK_SET, NULL);
        printf("load from stream %d\n", GdipCreateBitmapFromStream(ms, &re));
        printf("stream bitmap same pixels %s\n", same_bitmap(bmp, re, 32, 32) ? "yes" : "no");
        GdipDisposeImage(re);
        ms->lpVtbl->Release(ms);
    }
    // encoders
    {
        UINT n = 0, sz = 0;
        GdipGetImageEncodersSize(&n, &sz);
        printf("encoders %u\n", n);
        unsigned char *buf = malloc(sz);
        GdipGetImageEncoders(n, sz, buf);
        int found = 0;
        for (UINT i = 0; i < n; i++) {
            const CLSID *c = (const CLSID *)(buf + i * (sizeof(void *) == 8 ? 104 : 76));
            if (memcmp(c, &CLSID_PNG, sizeof(CLSID)) == 0) found = 1;
        }
        printf("png encoder %s\n", found ? "found" : "missing");
        free(buf);
    }
    GdipDisposeImage(bmp);
}

static void decode_tests(void) {
    for (size_t k = 0; k < sizeof timages / sizeof timages[0]; k++) {
        const TImage *ti = &timages[k];
        H img = NULL;
        IStream *ms = NULL;
        GpStatus st;
        if (k % 2 == 0) {
            HGLOBAL hg = GlobalAlloc(GMEM_MOVEABLE, ti->size);
            memcpy(GlobalLock(hg), ti->data, ti->size); GlobalUnlock(hg);
            CreateStreamOnHGlobal(hg, TRUE, &ms);
        } else ms = SHCreateMemStream(ti->data, ti->size);
        st = GdipCreateBitmapFromStream(ms, &img);
        if (st) { printf("%s load failed %d\n", ti->name, st); ms->lpVtbl->Release(ms); continue; }
        UINT w = 0, h = 0; int pf = 0;
        GdipGetImageWidth(img, &w); GdipGetImageHeight(img, &h); GdipGetImagePixelFormat(img, &pf);
        printf("%s %ux%u\n", ti->name, w, h);
        if (ti->pf) printf("%s format %X\n", ti->name, pf);
        const TSample *s = ti->ref;
        int bad = 0;
        for (int i = 0; i < ti->nref; i++) {
            UINT v = 0;
            GdipBitmapGetPixel(img, s[i].x, s[i].y, &v);
            if (ti->kind == 1) { if (!near_c(v & 0xFFFFFF, s[i].argb & 0xFFFFFF, 8) || (v >> 24) != 255) { bad++; printf("  %s %d,%d got %08X want %08X\n", ti->name, s[i].x, s[i].y, v, s[i].argb); } }
            else { if ((v >> 24) == 0) v = 0; printf("%s %d,%d %08X\n", ti->name, s[i].x, s[i].y, v); }
        }
        if (ti->kind == 1) printf("%s samples %s\n", ti->name, bad ? "bad" : "ok");
        if (ti->kind == 2) {
            UINT frames = 0, size = 0;
            GdipImageGetFrameCount(img, &DIM_TIME, &frames);
            unsigned delay = 0;
            if (GdipGetPropertyItemSize(img, 0x5100, &size) == 0) {
                unsigned char *item = malloc(size);
                GdipGetPropertyItem(img, 0x5100, size, item);
                void *val = *(void **)(item + (sizeof(void *) == 8 ? 16 : 12));
                delay = *(unsigned *)val;
                free(item);
            }
            printf("%s frames %u delay %u\n", ti->name, frames, delay);
            GdipImageSelectActiveFrame(img, &DIM_TIME, 1);
            const TSample *s1 = ti->ref1;
            for (int i = 0; i < ti->nref; i++) {
                UINT v = 0;
                GdipBitmapGetPixel(img, s1[i].x, s1[i].y, &v);
                if ((v >> 24) == 0) v = 0;
                printf("%s frame1 %d,%d %08X\n", ti->name, s1[i].x, s1[i].y, v);
            }
        }
        GdipDisposeImage(img);
        ms->lpVtbl->Release(ms);
    }
}

static void corrupt_tests(void) {
    int total = 0, rejected = 0;
    for (size_t k = 0; k < sizeof timages / sizeof timages[0]; k++) {
        const TImage *ti = &timages[k];
        unsigned char *copy = malloc(ti->size);
        // truncated copies
        unsigned cuts[3] = { 8, ti->size / 3, ti->size - 7 };
        for (int c = 0; c < 3; c++) {
            memcpy(copy, ti->data, ti->size);
            IStream *ms = SHCreateMemStream(copy, cuts[c]);
            H img = NULL;
            GpStatus st = GdipCreateBitmapFromStream(ms, &img);
            if (st == 0) GdipDisposeImage(img);
            ms->lpVtbl->Release(ms);
            if (c == 0) { total++; if (st) rejected++; }   // a bare signature must always be rejected
        }
        // garbled data: must not crash (any status)
        for (int c = 0; c < 4; c++) {
            memcpy(copy, ti->data, ti->size);
            for (unsigned i = 20 + c * 7; i < ti->size; i += 13 + c) copy[i] ^= (unsigned char)(0x5A + c);
            IStream *ms = SHCreateMemStream(copy, ti->size);
            H img = NULL;
            if (GdipCreateBitmapFromStream(ms, &img) == 0) GdipDisposeImage(img);
            ms->lpVtbl->Release(ms);
        }
        free(copy);
    }
    printf("truncated images rejected: %d of %d\n", rejected, total);
    {
        const char *junk = "this is not an image file at all, just some text";
        IStream *ms = SHCreateMemStream((const BYTE *)junk, (UINT)strlen(junk));
        H img = NULL;
        printf("text file rejected: %s\n", GdipCreateBitmapFromStream(ms, &img) != 0 ? "yes" : "no");
        ms->lpVtbl->Release(ms);
        printf("missing file rejected: %s\n", GdipCreateBitmapFromFile(wide("no_such_file.png"), &img) != 0 ? "yes" : "no");
    }
}

int main(void) {
    ULONG_PTR token = 0;
    StartupInput in = { 1, NULL, FALSE, FALSE };
    printf("startup %d\n", GdiplusStartup(&token, &in, NULL));
    graphics_tests();
    path_region_tests();
    bitmap_tests();
    decode_tests();
    corrupt_tests();
    GdiplusShutdown(token);
    printf("done\n");
    return 0;
}
